import{_ as e,o as r,c as t,O as n}from"./chunks/framework.db831a78.js";const h=JSON.parse('{"title":"工具 & 运维","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/10-工具运维.md","filePath":"interview/后端/Java/10-工具运维.md","lastUpdated":1788851914000}'),s={name:"interview/后端/Java/10-工具运维.md"};function a(d,o,l,g,i,c){return r(),t("div",null,o[0]||(o[0]=[n('<h1 id="工具-运维" tabindex="-1">工具 &amp; 运维 <a class="header-anchor" href="#工具-运维" aria-label="Permalink to &quot;工具 &amp; 运维&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><blockquote><p><strong>本篇策略</strong>：这一章是「实战感」最强的一章。<strong>线上排查流程、Linux 命令、越权防护</strong>我都有真实经历，要重点讲；删库恢复属于场景题，讲思路就行。</p></blockquote><hr><h2 id="_1-git-常用命令、merge-与-rebase-区别-★★☆" tabindex="-1">1. Git 常用命令、merge 与 rebase 区别 ★★☆ <a class="header-anchor" href="#_1-git-常用命令、merge-与-rebase-区别-★★☆" aria-label="Permalink to &quot;1. Git 常用命令、merge 与 rebase 区别 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 常用命令不用背，写代码天天用。 核心区别：</p><ul><li><strong>merge</strong>：保留分支历史，多一个合并提交，历史是分叉的 —— 安全。</li><li><strong>rebase</strong>：把自己的提交挪到目标分支后面，历史是<strong>一条直线</strong>，但会改写提交记录 —— 所以<strong>只能用在没推送出去的本地分支</strong>。</li><li><strong>reset vs revert</strong>：reset 移动 HEAD 会丢提交；revert 生成一个反向提交，历史保留，更安全。</li></ul><p><strong>我的项目关联</strong> 日常使用层面。<strong>真实习惯</strong>：个人 feature 分支我会先 rebase 拉平历史再提 MR，公共分支（main / develop）绝对不 rebase，只用 merge，避免把别人的提交历史搞乱。</p><p><strong>面试答题话术</strong> 「merge 保留历史、安全；rebase 历史干净但是改写提交，只能用在没推送的个人分支。我们团队规范就是：个人分支 rebase 保持整洁，公共分支只 merge。回退线上问题用 revert，不用 reset，因为 reset 会丢历史。」</p><hr><h2 id="_2-maven-依赖冲突-★★☆" tabindex="-1">2. Maven 依赖冲突 ★★☆ <a class="header-anchor" href="#_2-maven-依赖冲突-★★☆" aria-label="Permalink to &quot;2. Maven 依赖冲突 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> A 依赖 B(1.0)、C 依赖 B(2.0)，同时引进来就冲突。 Maven 默认两个原则：<strong>最短路径优先</strong>、<strong>最先声明优先</strong>。 解决手段：<code>&lt;exclusion&gt;</code> 排除、<code>dependencyManagement</code> 统一锁版本，用 <code>mvn dependency:tree</code> 看依赖树定位。</p><p><strong>我的项目关联</strong><strong>真实遇到过</strong>：多模块项目里不同模块引了不同版本的公共库，出现 <code>NoSuchMethodError</code> 这种运行时报错（编译能过，运行才炸），就是用 <code>dependency:tree</code> 定位后统一版本解决的。这类问题在 Spring Boot 多模块项目里挺常见。</p><p><strong>面试答题话术</strong> 「Maven 冲突默认按最短路径和最先声明来选版本。定位靠 <code>dependency:tree</code>。我们真遇到过——多模块引了不同版本，编译能过但运行时 <code>NoSuchMethodError</code>，就是依赖冲突。解决方式是 <code>dependencyManagement</code> 统一版本，或者 exclusion 排除。」</p><hr><h2 id="_3-docker-基础概念-★★☆" tabindex="-1">3. Docker 基础概念 ★★☆ <a class="header-anchor" href="#_3-docker-基础概念-★★☆" aria-label="Permalink to &quot;3. Docker 基础概念 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 镜像（只读模板、分层构建）、容器（镜像的运行实例、共享宿主机内核）、Dockerfile（构建脚本）、仓库（Harbor / Docker Hub）。 和虚拟机的区别：虚拟机虚拟一整套 OS（重、隔离彻底），容器共享内核（轻、秒级启动、隔离弱一些）。 分层的好处：公共层可复用，构建和传输都省。</p><p><strong>我的项目关联</strong><strong>真实环境</strong>：我们后端服务都是容器化部署的，镜像推到私有仓库，K8s 拉起。<strong>真实踩过的坑</strong>跟 JVM 有关 —— 容器有内存限制，如果 JVM 不显式设堆大小，可能被 OOM Killer 干掉（进程 exit 137），这个在 02 笔记里详细讲过，是<strong>真实踩过的</strong>。</p><p><strong>面试答题话术</strong> 「镜像是模板、容器是运行实例，共享宿主机内核所以比虚拟机轻。我们服务都是容器化部署的。这里有个真实的坑：容器内存限制和 JVM 堆要配套设置，不设堆大小容易触发 OOM Killer 把进程杀掉，我们是踩过的。」</p><hr><h2 id="_4-linux-常用命令-进程、日志、端口、内存-cpu-★★★-【简历亮点-高频追问】" tabindex="-1">4. Linux 常用命令：进程、日志、端口、内存 CPU ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_4-linux-常用命令-进程、日志、端口、内存-cpu-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;4. Linux 常用命令：进程、日志、端口、内存 CPU ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 按场景记，别背清单：</p><ul><li>进程 / CPU：<code>top</code>、<code>ps -ef | grep</code>、<code>kill -9</code>、<code>nohup ... &amp;</code></li><li>日志：<code>tail -f</code>、<code>grep</code>、<code>less</code></li><li>端口：<code>netstat -tlnp</code>、<code>ss -tlnp</code>、<code>lsof -i:8080</code></li><li>资源：<code>free -h</code>（内存）、<code>df -h</code>（磁盘）、<code>du -sh *</code>（目录大小）</li><li>文件：<code>find</code>、<code>chmod</code>、<code>tar -zxvf</code></li></ul><p><strong>我的项目关联</strong><strong>这是真实排障现场</strong>。举两个真实场景：</p><ol><li><strong>服务起不来</strong>：先 <code>netstat -tlnp | grep 端口</code> 看端口是不是被占了，再 <code>ps -ef</code> 看有没有残留进程。</li><li><strong>磁盘告警</strong>：<code>df -h</code> 看到某个分区满，再 <code>du -sh *</code> 逐层找，多半是日志没清理。 这些都是<strong>线上真实用过的</strong>手段。</li></ol><p><strong>面试答题话术</strong> 「Linux 我按场景记：排查端口冲突用 netstat 加 grep，找日志用 tail -f 和 grep，看资源用 top、free、df。真实例子——服务起不来我第一反应是查端口是不是被占了；磁盘告警我一般先 <code>df -h</code> 再 <code>du -sh *</code> 逐层找，基本都是日志没清。」</p><hr><h2 id="_5-常见安全-xss、csrf、sql-注入-★★★-【简历亮点-高频追问】" tabindex="-1">5. 常见安全：XSS、CSRF、SQL 注入 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-常见安全-xss、csrf、sql-注入-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 常见安全：XSS、CSRF、SQL 注入 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>SQL 注入</strong>：用户输入被当成 SQL 拼进去了（<code>&#39; OR &#39;1&#39;=&#39;1</code>）。防御核心是<strong>预编译</strong>（<code>#{}</code> / PreparedStatement），让参数只能当值、不能当语法。</li><li><strong>XSS</strong>：恶意脚本被注入页面执行，偷 cookie。防御：输出转义、CSP、HttpOnly、输入过滤。</li><li><strong>CSRF</strong>：诱导你在已登录状态下点恶意链接，冒充你发请求。防御：CSRF Token、SameSite Cookie、校验 Referer。</li><li>区别一句话：<strong>XSS 是注入脚本利用「用户」，CSRF 是利用「登录态」冒用身份</strong>。</li><li>密码存法：<strong>加盐哈希</strong>（BCrypt），不能明文、不能裸 MD5。</li></ul><p><strong>我的项目关联</strong><strong>真实遵守的规范</strong>：所有 SQL 走 MyBatis 的 <code>#{}</code> 预编译，<strong>禁止用 <code>${}</code> 拼接</strong>（05 笔记专门讲过这个坑）；密码一律 BCrypt 加盐存储；对外接口加了 token 校验和签名。这些是<strong>线上真实在执行的安全基线</strong>。</p><p><strong>面试答题话术</strong> 「三个我先分清楚：SQL 注入靠预编译防，我们 MyBatis 全部用 <code>#{}</code>，禁 <code>${}</code> 拼接；XSS 靠输出转义加 HttpOnly；CSRF 靠 token 加 SameSite。密码我们统一 BCrypt 加盐，绝不明文也不裸 MD5。这些是项目里硬性要求的。」</p><hr><h2 id="_6-越权漏洞-idor-★★★-【简历亮点-高频追问】" tabindex="-1">6. 越权漏洞（IDOR）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_6-越权漏洞-idor-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;6. 越权漏洞（IDOR）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>水平越权</strong>：A 用户改一下 URL 里的 id 就能看到 B 用户的数据（同级别）。</li><li><strong>垂直越权</strong>：普通用户访问了管理员功能。</li><li>防御关键：<strong>服务端必须做资源归属校验</strong>，前端隐藏按钮不算安全措施。</li></ul><p><strong>我的项目关联</strong><strong>真实场景</strong>：充电订单、钱包、发票这些接口，如果不校验归属，改个订单号就能看别人的。我们的做法是<strong>查询时强制带上当前用户的身份条件</strong>，不是查到再判断。<strong>这是安全底线，不是说说的</strong>。前端虽然也做了隐藏，但服务端校验才是真的。</p><p><strong>面试答题话术</strong> 「水平越权就是改 id 看别人数据，垂直越权是低权限干高权限的事。防护的核心是服务端做资源归属校验——我们的做法是查询就带当前用户条件，而不是查出结果再判断，这样从根上避免越权。前端隐藏按钮只能算体验优化，不是安全措施。」</p><hr><h2 id="_7-线上排查完整流程-★★★-【简历亮点-高频追问】" tabindex="-1">7. 线上排查完整流程 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_7-线上排查完整流程-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;7. 线上排查完整流程 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 五步：确认现象（报错、影响范围、能否复现）→ 看监控（CPU/内存/GC/慢 SQL/错误率）→ 看日志（错误堆栈）→ 定位（分头查）→ 修复 + 验证 + 复盘加监控。 定位的口诀：</p><ul><li>CPU 高 → <code>top</code> + <code>top -Hp</code> + <code>jstack</code></li><li>内存高 / OOM → dump + MAT</li><li>响应慢 → 慢 SQL、下游服务、GC 频率</li><li>报错 → 直接看堆栈</li></ul><p><strong>我的项目关联</strong><strong>这是我最能讲的实战环节</strong>。真实流程：接口报警 → 看监控确认是耗时还是错误率 → 抓 traceId 串联日志 → 定位到底是慢 SQL 还是下游。<strong>真实案例</strong>：接口偶发变慢，最后定位是 Redis 大 key 阻塞（06 笔记讲过），这整个排查链路我是真的走过。</p><p><strong>面试答题话术</strong> 「排查我按固定套路：先确认现象和影响面，再看监控判断是资源问题还是逻辑问题，然后抓 traceId 串日志定位。具体分四种：CPU 高就 top 加 jstack，内存高就 dump 加 MAT，慢就查慢 SQL 和下游，报错直接看堆栈。最后一定要复盘加监控——光修完不加告警，下次还会被打个措手不及。」</p><hr><h2 id="_8-线程-dump-分析-★★☆" tabindex="-1">8. 线程 dump 分析 ★★☆ <a class="header-anchor" href="#_8-线程-dump-分析-★★☆" aria-label="Permalink to &quot;8. 线程 dump 分析 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><code>jstack pid &gt; dump.txt</code> 导出线程快照，看线程状态：<code>BLOCKED</code>（等锁）、<code>WAITING</code>、<code>RUNNABLE</code>。JDK 自带的死锁检测也会直接打印出来。 大量 BLOCKED 说明锁竞争严重，要找「谁持有锁」。</p><p><strong>我的项目关联</strong><strong>真实用过</strong>：排查 CPU 飙高时配合 <code>top -Hp</code> 把线程 id 转成十六进制，再在 jstack 里搜，定位到具体代码行。和 02 笔记里讲的是同一套手法。</p><p><strong>面试答题话术</strong> 「jstack 导出线程快照，重点看 BLOCKED 和死锁检测。排查 CPU 高的标准动作是 top 找进程、top -Hp 找线程、转成十六进制去 jstack 里搜，定位到代码行。这个流程我实际用过。」</p><hr><h2 id="_9-jvm-调优参数-★★☆" tabindex="-1">9. JVM 调优参数 ★★☆ <a class="header-anchor" href="#_9-jvm-调优参数-★★☆" aria-label="Permalink to &quot;9. JVM 调优参数 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 见 02-JVM 篇。核心几个：<code>-Xms</code> / <code>-Xmx</code>（堆）、<code>-XX:+UseG1GC</code>、<code>-XX:MaxGCPauseMillis</code>、OOM 时 dump。<strong>容器环境尤其要显式设堆</strong>。</p><p><strong>我的项目关联</strong><strong>真实经验</strong>：容器部署 + JVM 堆要配套。我们是显式设 <code>-Xmx</code> 的，不然容器内存限制和 JVM 认知不一致，会被 OOM Killer 杀（exit 137）。这是<strong>真实踩过的坑</strong>，详见 02 笔记。</p><p><strong>面试答题话术</strong> 「调优参数核心就是堆大小、G1、GC 暂停目标、OOM dump。容器里最关键的是显式设 <code>-Xmx</code>，让 JVM 知道容器限制，防止被 OOM Killer 干掉。我们踩过这个坑。」</p><hr><h2 id="_10-日志框架与监控体系-★★☆" tabindex="-1">10. 日志框架与监控体系 ★★☆ <a class="header-anchor" href="#_10-日志框架与监控体系-★★☆" aria-label="Permalink to &quot;10. 日志框架与监控体系 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 日志：SLF4J 门面 + Logback 实现，级别 TRACE/DEBUG/INFO/WARN/ERROR，结构化 JSON + traceId 贯穿，<strong>不打印敏感信息</strong>。 监控：指标 Prometheus + Grafana，链路 SkyWalking，日志 ELK，阈值告警。</p><p><strong>我的项目关联</strong><strong>真实在用的</strong>：日志打 traceId 贯穿全链路，方便排查时串起来；监控有接口耗时和错误率告警。<strong>注意点</strong>：手机号、身份证这类敏感字段我们打印时会脱敏。</p><p><strong>面试答题话术</strong> 「日志用 SLF4J 加 Logback，关键是打好 traceId 方便串链路，敏感字段必须脱敏。监控是指标用 Prometheus 加 Grafana、链路用 SkyWalking、日志用 ELK。我们用 traceId 排查时特别方便。」</p><hr><h2 id="_11-如果程序员删库跑路了-怎么恢复数据-★★★-场景题" tabindex="-1">11. 如果程序员删库跑路了，怎么恢复数据 ★★★ （场景题） <a class="header-anchor" href="#_11-如果程序员删库跑路了-怎么恢复数据-★★★-场景题" aria-label="Permalink to &quot;11. 如果程序员删库跑路了，怎么恢复数据 ★★★ （场景题）&quot;">​</a></h2><p><strong>通俗理解</strong> 思路三步走：</p><ol><li><strong>止损</strong>：立刻停写、锁访问，别再让数据被覆盖。</li><li><strong>恢复</strong>：先恢复最近的全量备份，再用 binlog 增量回放到删库前一刻（过滤掉 drop/delete）。</li><li><strong>救命</strong>：如果从库没被同步删掉（尤其延迟从库），直接从从库捞。 <strong>预防比恢复更重要</strong>：定期全量备份 + 开 binlog + 异地备份、延迟从库、生产库不给开发 drop 权限、删除走逻辑删除、定期做恢复演练。</li></ol><p><strong>我的项目关联</strong><strong>面试说明</strong>：这是场景题，我们没有真经历过删库（也不希望）。但我们<strong>做了预防措施</strong>：生产库权限最小化、删除走逻辑删除（<code>is_deleted</code> 标记）、关键表定期备份。这里我只能讲方案，不会说成自己救过库。</p><p><strong>面试答题话术</strong> 「这个题我讲思路：先止损停写，然后全量备份恢复加 binlog 回放到删库前，如果从库还在就直接从从库捞。关键点是要把 binlog 里删库那一段过滤掉。但重点其实是预防——权限最小化、逻辑删除、延迟从库、定期演练。我们项目做到的是逻辑删除和权限控制，删库恢复本身没真实经历过。」</p><hr><h2 id="_12-删除数据的几种恢复手段-★★☆" tabindex="-1">12. 删除数据的几种恢复手段 ★★☆ <a class="header-anchor" href="#_12-删除数据的几种恢复手段-★★☆" aria-label="Permalink to &quot;12. 删除数据的几种恢复手段 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li>备份恢复：全量备份 + binlog 增量回放。</li><li>延迟从库：故意慢同步，主库误删时从库还有数据。</li><li>闪回（Flashback）：把 binlog 里的 delete/update 反向解析成 insert/update，工具如 binlog2sql、MyFlash。</li><li>回收站：部分云数据库支持 drop 先入回收站。</li></ul><p><strong>我的项目关联</strong><strong>通用坑，了解层面</strong>。我们用逻辑删除规避了大部分误删风险，闪回、回收站这些没实操过。</p><p><strong>面试答题话术</strong> 「恢复手段有备份加 binlog 回放、延迟从库、binlog 闪回反向解析、云上的回收站。闪回的原理就是把 delete 反转成 insert。这些我了解原理，实际我们用逻辑删除来规避。」</p><hr><h2 id="_13-在线调试工具-arthas-★★☆-【简历亮点-高频追问】" tabindex="-1">13. 在线调试工具 Arthas ★★☆ 【简历亮点，高频追问】 <a class="header-anchor" href="#_13-在线调试工具-arthas-★★☆-【简历亮点-高频追问】" aria-label="Permalink to &quot;13. 在线调试工具 Arthas ★★☆ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 阿里开源的 Java 在线诊断工具，<strong>不用重启、不用改代码</strong>，attach 到运行中的 JVM。最常用的几个命令：</p><ul><li><code>dashboard</code>：总览线程/内存/GC</li><li><code>thread -n 3</code>：最忙的 3 个线程；<code>thread -b</code> 直接找死锁</li><li><code>trace 类 方法</code>：看方法调用耗时，定位性能瓶颈</li><li><code>watch 类 方法 &#39;{params, returnObj, throwExp}&#39;</code>：看入参、返回值、异常</li><li><code>jad 类名</code>：反编译，确认线上跑的到底是哪个版本的代码</li></ul><p><strong>我的项目关联</strong><strong>真实用过，而且是排障利器</strong>。最有用的三个场景：</p><ol><li><strong>怀疑线上代码没生效</strong>：用 <code>jad</code> 反编译确认版本，比猜靠谱。</li><li><strong>接口慢</strong>：用 <code>trace</code> 找耗时方法。</li><li><strong>不知道方法入参长啥样</strong>：用 <code>watch</code> 直接看，不用加日志重新发版。 跟 jstack/jmap 的区别：那些是 JDK 自带、功能单一；Arthas 更强大，能交互式在线诊断。</li></ol><p><strong>面试答题话术</strong> 「Arthas 我最常用三个命令：<code>jad</code> 确认线上代码版本、<code>trace</code> 定位慢方法、<code>watch</code> 看方法的入参和异常。最大价值是<strong>不用重启不用改代码</strong>就能在线诊断。相比 jstack、jmap，它功能更全，是交互式的。这个我用得比较熟。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>Jenkins / CI-CD</strong>：代码提交自动构建、测试、发布，知道流水线概念即可。</li><li><strong>Nginx 常用配置</strong>：反向代理、负载均衡、静态资源、限流，运维层面了解。</li><li><strong>JProfiler / VisualVM</strong>：本地性能分析工具，Arthas 能覆盖大部分线上需求，知道名字就行。</li><li><strong>SkyWalking vs Zipkin</strong>：都是链路追踪，SkyWalking 对 Java 更友好、无侵入，知道定位就行。</li></ul>',81)]))}const u=e(s,[["render",a]]);export{h as __pageData,u as default};
